CREATE OR REPLACE FUNCTION public.vip_member_flag()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid := coalesce(new.profile_id, old.profile_id);
begin
  perform set_config('tryp.vip_write', 'on', true);
